@page "/settings"
@rendermode InteractiveServer
@using sv_f10828ca1b37477cb2125a2bbac8b0d9.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="nav-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                    <span class="nav-icon">@GetSectionIcon(section)</span>
                    @section
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            <!-- Toast notification -->
            @if (_showToast)
            {
                <div class="toast-message @(_toastType)">
                    @_toastMessage
                    <button class="toast-close" @onclick="() => _showToast = false">&times;</button>
                </div>
            }

            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfile()
                    break;
                case "Notifications":
                    @RenderNotifications()
                    break;
                case "Security":
                    @RenderSecurity()
                    break;
                case "Appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

@* ───── Profile Section ───── *@
@{ RenderFragment RenderProfile() =>
    @<div class="section-panel">
        <h3>Profile</h3>
        <p class="text-muted">Manage your personal information</p>
        <hr />

        <div class="avatar-area">
            <img src="@_editProfile!.AvatarUrl" alt="Avatar" class="avatar-preview" />
            <span class="avatar-url text-muted">@_editProfile.AvatarUrl</span>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input class="form-control" @bind="_editProfile.DisplayName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input class="form-control" type="email" @bind="_editProfile.Email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="3" @bind="_editProfile.Bio"></textarea>
        </div>

        <div class="btn-group-actions">
            <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    </div>;
}

@* ───── Notifications Section ───── *@
@{ RenderFragment RenderNotifications() =>
    @<div class="section-panel">
        <h3>Notifications</h3>
        <p class="text-muted">Choose how you want to be notified</p>
        <hr />

        <div class="toggle-row">
            <div>
                <strong>Email Notifications</strong>
                <p class="text-muted mb-0">Receive updates via email</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       @bind="_editNotifications!.EmailNotifications" />
            </div>
        </div>
        <div class="toggle-row">
            <div>
                <strong>Push Notifications</strong>
                <p class="text-muted mb-0">Receive push notifications in your browser</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       @bind="_editNotifications.PushNotifications" />
            </div>
        </div>
        <div class="toggle-row">
            <div>
