@page "/settings"
@rendermode InteractiveServer
@using sv_f10828ca1b37477cb2125a2bbac8b0d9.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="nav-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                    <span class="nav-icon">@GetSectionIcon(section)</span>
                    @section
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            <!-- Toast notification -->
            @if (_showToast)
            {
                <div class="toast-message @(_toastType)">
                    @_toastMessage
                    <button class="toast-close" @onclick="() => _showToast = false">&times;</button>
                </div>
            }

            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfile()
                    break;
                case "Notifications":
                    @RenderNotifications()
                    break;
                case "Security":
                    @RenderSecurity()
                    break;
                case "Appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

