            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       @bind="_editNotifications.PushNotifications" />
            </div>
        </div>
        <div class="toggle-row">
            <div>
                <strong>Weekly Digest</strong>
                <p class="text-muted mb-0">Get a summary email every week</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       @bind="_editNotifications.WeeklyDigest" />
            </div>
        </div>

        <h5 class="mt-4">Muted Channels</h5>
        <div class="channel-list">
            @foreach (var channel in _editNotifications.Channels)
            {
                <div class="form-check">
                    <input class="form-check-input darker-border-checkbox" type="checkbox"
                           id="@($"ch-{channel.Name}")"
                           @bind="channel.Muted" />
                    <label class="form-check-label" for="@($"ch-{channel.Name}")">
                        #@channel.Name
                    </label>
                </div>
            }
        </div>

        <div class="btn-group-actions mt-3">
            <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Preferences
            </button>
        </div>
    </div>;
}

@* ───── Security Section ───── *@
@{ RenderFragment RenderSecurity() =>
    @<div class="section-panel">
        <h3>Security</h3>
        <p class="text-muted">Manage your account security</p>
        <hr />

        <!-- Change Password expandable -->
        <div class="expandable-panel">
            <button class="expandable-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="expand-icon">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="expandable-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input class="form-control" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input class="form-control" type="password" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input class="form-control" type="password" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Update Password
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="toggle-row mt-3">
            <div>
                <strong>Two-Factor Authentication</strong>
                <p class="text-muted mb-0">
                    Status:
                    <span class="badge @(_security!.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_security.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@_security.TwoFactorEnabled" disabled />
            </div>
        </div>

        @if (_security.LastPasswordChange.HasValue)
        {
            <p class="text-muted mt-2 mb-0">
                Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        <!-- Active Sessions -->
        <h5 class="mt-4">Active Sessions</h5>
        <div class="table-responsive">
            <table class="table table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _security.Sessions)
                    {
                        var isCurrent = session.Id == _security.Sessions[0].Id;
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (isCurrent)
                                {
                                    <span class="badge bg-info">Current</span>
                                }
                                else
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => ConfirmRevokeSession(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke confirmation dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-backdrop show"></div>
            <div class="modal d-block" tabindex="-1">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="RevokeSession" disabled="@_saving">
                                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                Revoke
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>;
}

@* ───── Appearance Section ───── *@
@{ RenderFragment RenderAppearance() =>
    @<div class="section-panel">
        <h3>Appearance</h3>
        <p class="text-muted">Customize how the app looks</p>
        <hr />

        <div class="mb-4">
            <label class="form-label fw-bold">Theme</label>
            <div class="d-flex gap-3">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{theme}")"
                               value="@theme"
                               checked="@(_editAppearance!.Theme == theme)"
                               @onchange="() => _editAppearance!.Theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-4">
            <label class="form-label fw-bold">Font Size</label>
            <div class="d-flex gap-3">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"size-{size}")"
                               value="@size"
                               checked="@(_editAppearance!.FontSize == size)"
                               @onchange="() => _editAppearance!.FontSize = size" />
                        <label class="form-check-label" for="@($"size-{size}")">@size</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-4">
            <label class="form-label fw-bold">Language</label>
            <select class="form-select" style="max-width: 250px;"
                    @bind="_editAppearance!.Language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
            </select>
        </div>

        <div class="toggle-row">
            <div>
                <strong>Compact Mode</strong>
                <p class="text-muted mb-0">Reduce spacing and padding throughout the UI</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       @bind="_editAppearance!.CompactMode" />
            </div>
        </div>

        <!-- Live preview -->
        <h5 class="mt-4">Preview</h5>
        <div class="appearance-preview @(_editAppearance.Theme.ToLowerInvariant()) @(_editAppearance.CompactMode ? "compact" : "")"
             style="font-size: @GetPreviewFontSize();">
            <div class="preview-header">
                <strong>Sample Header</strong>
                <span class="badge bg-primary">@_editAppearance.Theme</span>
            </div>
            <p class="preview-text">
                This is a preview of your selected appearance settings.
                Font size is <em>@_editAppearance.FontSize</em>, language is <em>@_editAppearance.Language</em>.
            </p>
            <button class="btn btn-sm btn-primary">Sample Button</button>
        </div>

        <div class="btn-group-actions mt-3">
            <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        </div>
    </div>;
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;
    private bool _saving;

    // Toast
    private bool _showToast;
    private string _toastMessage = "";
    private string _toastType = "success";

    // Profile
    private ProfileEdit? _editProfile;
    private UserProfile? _savedProfile;

    // Notifications
    private NotificationsEdit? _editNotifications;

    // Security
    private SecuritySettings? _security;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceEdit? _editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

        _savedProfile = profileTask.Result;
        _editProfile = ProfileEdit.From(_savedProfile);
        _editNotifications = NotificationsEdit.From(notifsTask.Result);
        _security = securityTask.Result;
        _editAppearance = AppearanceEdit.From(appearanceTask.Result);
    }

    private void SetActiveSection(string section)
    {
        _activeSection = section;
        _showToast = false;
    }

    private async Task ShowToast(string message, string type = "success")
    {
        _toastMessage = message;
        _toastType = type;
        _showToast = true;
        StateHasChanged();
        await Task.Delay(4000);
        _showToast = false;
    }

    // ── Profile ──
    private async Task SaveProfile()
    {
        _saving = true;
        var profile = new UserProfile(_editProfile!.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        _ = ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        _editProfile = ProfileEdit.From(_savedProfile!);
    }

    // ── Notifications ──
    private async Task SaveNotifications()
    {
        _saving = true;
        var mutedChannels = _editNotifications!.Channels
            .Where(c => c.Muted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _ = ShowToast("Notification preferences saved!");
    }

    // ── Security ──
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            _ = ShowToast("Please fill in all password fields.", "error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _ = ShowToast("New passwords do not match.", "error");
            return;
        }

        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = _newPassword = _confirmPassword = "";
        _passwordPanelOpen = false;
        _saving = false;
        _security = await SettingsService.GetSecuritySettingsAsync();
        _ = ShowToast("Password updated successfully!");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task RevokeSession()
    {
        _saving = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke!.Id);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        _saving = false;
        _ = ShowToast("Session revoked.");
    }

    // ── Appearance ──
    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(
            _editAppearance!.Theme,
            _editAppearance.FontSize,
            _editAppearance.Language,
            _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _ = ShowToast("Appearance settings saved!");
    }

    private string GetPreviewFontSize() => _editAppearance?.FontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    // ── Mutable edit models ──
    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static ProfileEdit From(UserProfile p) =>
            new() { DisplayName = p.DisplayName, Email = p.Email, AvatarUrl = p.AvatarUrl, Bio = p.Bio };
    }

    private class NotificationsEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<ChannelEntry> Channels { get; set; } = [];

        public static NotificationsEdit From(NotificationPrefs prefs) =>
            new()
            {
                EmailNotifications = prefs.EmailNotifications,
                PushNotifications = prefs.PushNotifications,
                WeeklyDigest = prefs.WeeklyDigest,
                Channels = prefs.MutedChannels.Select(c => new ChannelEntry { Name = c, Muted = true }).ToList()
            };
    }

    private class ChannelEntry
    {
        public string Name { get; set; } = "";
        public bool Muted { get; set; }
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }

        public static AppearanceEdit From(AppearanceSettings s) =>
            new() { Theme = s.Theme, FontSize = s.FontSize, Language = s.Language, CompactMode = s.CompactMode };
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
}

/* ── Sidebar ── */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav .nav-item {
    padding: 0.65rem 1.25rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    color: #495057;
    font-weight: 500;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-nav .nav-item:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav .nav-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
}

.nav-icon {
    font-size: 1.1rem;
}

/* ── Main content ── */
.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    position: relative;
    max-width: 800px;
}

.section-panel h3 {
    margin-bottom: 0.25rem;
}

/* ── Toast ── */
.toast-message {
    position: sticky;
    top: 0;
    z-index: 100;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    animation: slideDown 0.25s ease;
}

.toast-message.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-message.error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    color: inherit;
    line-height: 1;
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Avatar ── */
.avatar-area {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.avatar-url {
    font-size: 0.8rem;
    word-break: break-all;
}

/* ── Toggle rows ── */
.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-row .form-check-input {
    width: 2.5em;
    height: 1.25em;
}

/* ── Channels ── */
.channel-list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem 1.5rem;
    padding: 0.5rem 0;
}

/* ── Action buttons ── */
.btn-group-actions {
    display: flex;
    gap: 0.5rem;
    padding-top: 1rem;
}

/* ── Expandable panel ── */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    overflow: hidden;
}

.expandable-header {
    width: 100%;
    background: #f8f9fa;
    border: none;
    padding: 0.75rem 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    font-weight: 500;
}

.expandable-header:hover {
    background: #e9ecef;
}

.expandable-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* ── Appearance preview ── */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    transition: all 0.2s ease;
}

.appearance-preview.light {
    background: #ffffff;
    color: #212529;
}

.appearance-preview.dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.appearance-preview.dark .btn-primary {
    background: #4a6fa5;
    border-color: #3d5f8c;
}

.appearance-preview.system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #495057;
}

.appearance-preview.compact {
    padding: 0.5rem 0.75rem;
}

.appearance-preview.compact .preview-text {
    margin-bottom: 0.25rem;
}

.preview-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
}

